import Foundation

// Recipe search, ported from src/lib/search.ts: fuzzy full-text (Fuse.js on the web) plus
// scoped `tag:`, `ing:` and `chef:` tokens. Every token must match (they AND together).
// RecipeSearchTests checks it against results generated by the web's own search.
enum RecipeSearch {
    /// Ids of the recipes matching `query`, or nil for an empty query (show everything).
    static func matches(in recipes: [Recipe], query: String) -> Set<String>? {
        let tokens = tokenize(query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased())
        guard !tokens.isEmpty else { return nil }
        let records = recipes.map(Record.init)
        var result = Set(recipes.map(\.id))
        for token in tokens {
            result.formIntersection(records.filter { $0.matches(token) }.map(\.id))
        }
        return result
    }

    /// `tag:"slow cooker"`, `chef:mike`, `"mike drop"` or a plain word, quotes removed
    /// (the token regex in searchRecipes). \w is spelled out because JS's is ASCII-only.
    static func tokenize(_ query: String) -> [String] {
        let pattern = #"(-?[A-Za-z0-9_]+:"[^"]+"|-?[A-Za-z0-9_]+:\S+|"[^"]+"|\S+)"#
        guard let regex = try? NSRegularExpression(pattern: pattern) else { return [] }
        let range = NSRange(query.startIndex..., in: query)
        return regex.matches(in: query, range: range).compactMap {
            Range($0.range, in: query).map { query[$0].replacingOccurrences(of: "\"", with: "") }
        }
    }

    /// One recipe's searchable text, lowercased (the `Rec` records in buildIndex).
    private struct Record {
        let id: String
        let fields: [String]  // the Fuse keys: title, description, each tag, ingredients, steps, chef
        let tags: [String]
        let ingredientsText: String
        let chef: String

        init(_ recipe: Recipe) {
            id = recipe.id
            tags = (recipe.tags ?? []).map { $0.lowercased() }
            ingredientsText = (recipe.ingredients ?? []).map { "\($0.amount ?? "") \($0.name)" }.joined(separator: "\n").lowercased()
            chef = recipe.chefName.lowercased()
            let instructions = (recipe.instructions ?? []).joined(separator: "\n").lowercased()
            fields = [recipe.title.lowercased(), (recipe.description ?? "").lowercased()] + tags + [ingredientsText, instructions, chef]
        }

        func matches(_ token: String) -> Bool {
            if let colon = token.firstIndex(of: ":"),
               token[..<colon].allSatisfy({ $0.isASCII && ($0.isLetter || $0.isNumber || $0 == "_") }),
               !token[..<colon].isEmpty {
                let scope = token[..<colon]
                let value = String(token[token.index(after: colon)...])
                switch scope {
                case "tag", "t": return tags.contains { $0.contains(value) || value.isEmpty }
                case "ing", "ingredient": return value.isEmpty || ingredientsText.contains(value)
                case "chef", "by": return value.isEmpty || chef.contains(value)
                default: break  // unknown scope: fuzzy-search the whole token, like the web
                }
            }
            let pattern = Array(token.utf16)
            return fields.contains { RecipeSearch.fuzzyContains(Array($0.utf16), pattern) }
        }
    }

    /// Fuse.js's match test with `threshold: 0.2, ignoreLocation: true`: somewhere in the text
    /// the pattern appears with at most 1 typo (insert, delete or swap a letter) per 5 letters.
    /// Fuse's Bitap search counts typos the same way; this is the plain dynamic-programming
    /// version. Works on UTF-16 like JavaScript strings. (Fuse also splits patterns over 32
    /// characters into chunks; search tokens are single words or short phrases, so that's skipped.)
    static func fuzzyContains(_ text: [UInt16], _ pattern: [UInt16]) -> Bool {
        let m = pattern.count
        guard m > 0 else { return true }
        let maxErrors = m / 5  // errors / length <= 0.2
        // Row i holds the fewest typos to match pattern[..<i] ending at each text position;
        // row 0 is all zeros because the match may start anywhere.
        var previous = [Int](repeating: 0, count: text.count + 1)
        var current = previous
        for i in 1...m {
            current[0] = i
            for j in stride(from: 1, through: text.count, by: 1) {
                let swap = previous[j - 1] + (pattern[i - 1] == text[j - 1] ? 0 : 1)
                current[j] = min(swap, previous[j] + 1, current[j - 1] + 1)
            }
            swap(&previous, &current)
        }
        return previous.min()! <= maxErrors
    }
}

extension Recipe {
    /// Kitchen nickname of whoever added the recipe ("By Nana" on the recipe page);
    /// old records say "user", which isn't one (chefName in search.ts).
    var chefName: String {
        let name = (createdByName ?? "").trimmingCharacters(in: .whitespaces)
        return name.lowercased() == "user" ? "" : name
    }
}
